"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1115-07-24:0":{"b": ["काउंटेस मटिल्डा की मृत्यु हुई; कानोस्सा राजवंश का अंत (विरासत पोपशाही और साम्राज्य के बीच विवाद का विषय बनी)", "4d3a851d"], "d": ["कानोस्सा राजवंश (कानोस्सा/मटिल्डा) समाप्त हुआ (निश्चितता: {\"f\": \"yuzyil\", \"t\": \"gun\"}) साथ ही 'Matilde di Canossa' https://www.treccani.it/enciclopedia/matilde-di-canossa/ : मटिल्डा की संपत्ति में ब्रेशिया, बेर्गामो, मंतोवा और अरेत्सो, सिएना, कोर्नेतो की काउंटियाँ सम्मिलित थीं।", "e54dd4f9"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1125-01-01:0":{"b": ["वेनिसवासियों ने समुद्री लुटेरों का अड्डा मोदोन ध्वस्त कर दिया", "788577af"], "d": ["मोदोन मध्य युग में छोटा किंतु सुदृढ़ प्राचीर वाला नौसैनिक अड्डा था, फिर समुद्री लुटेरों का अड्डा बन गया; वेनिसवासियों ने 1125 में उसे ध्वस्त कर दिया। क़स्बा 1205 में फ़्रैंकों द्वारा मोरिया लिए जाने तक खंडहर रहा।", "a24897f1"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1125-05-19:0":{"b": ["मोनोमाख की कीव में मृत्यु हुई; संयुक्त रूस का अंतिम शासक", "a4d61f0b"], "d": ["वोलोदिमिर मोनोमाख 19 मई 1125 को कीव में मरा। Encyclopedia of Ukraine उसे 'एकीकृत राज्य पर शासन करने वाला अंतिम रूसी राजकुमार' मानता है।", "cb8a41da"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1127-01-01:0":{"b": ["रोजर द्वितीय को रेज्जियो में सेना द्वारा ड्यूक घोषित किया गया", "e19f4cba"], "d": ["आपुलिया के ड्यूक विलियम द्वितीय की मृत्यु पर विरासत का दावा करने वाले रोजर को, 1127 के अंत में सिसिली लौटते समय रेज्जियो में उसकी सेना ने आपुलिया के ड्यूक के रूप में जयकार किया; पोप होनोरियस द्वितीय ने उसे बहिष्कृत किया।", "8f30bc01"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1127-01-01:1":{"b": ["ड्यूक विलियम द्वितीय निःसंतान मरा; ओतविल वंश आपुलिया में समाप्त हुआ", "43535228"], "d": ["ड्यूक विलियम द्वितीय निःसंतान मरता है (जून/जुलाई 1127); ओतविल वंश आपुलिया में समाप्त होता है, रोजर द्वितीय विरासत का दावा करता है।", "d5eca822"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1128-08-22:0":{"b": ["बेनेवेंतो के निकट पोप होनोरियस द्वितीय ने रोजर द्वितीय को आपुलिया, कलाब्रिया और सिसिली का ड्यूक माना", "67e94015"], "d": ["22 अगस्त 1128 को बेनेवेंतो के निकट पोप ने रोजर को आपुलिया, कलाब्रिया और सिसिली के ड्यूक के रूप में निवेशित किया; बदले में बेनेवेंतो पर पोपीय नियंत्रण और कापुआ रियासत की अनुल्लंघनीयता सुनिश्चित की गई। आपुलिया ड्यूक-राज्य सिसिली काउंटी के साथ एक हुआ।", "08889c27"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1130-12-25:0":{"b": ["रोजर द्वितीय का पालेर्मो में सिसिली के राजा के रूप में राज्याभिषेक हुआ", "edd9c9d4"], "d": ["पोप होनोरियस द्वितीय की मृत्यु (13 फ़रवरी 1130) के बाद उठे विभेद में अनाक्लेतुस द्वितीय से राजमुकुट पाने वाला रोजर 27 सितंबर 1130 को निवेशित किया गया; क्रिसमस के दिन पालेर्मो में राजा के रूप में मुकुट पहना। राज्य में सिसिली द्वीप और अब्रूत्सी तक का दक्षिणी इटली सम्मिलित था।", "2fc371e4"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1134-01-01:0":{"b": ["राजा स्वेरकर ने स्वीडन में स्वेआ और गोट लोगों को स्थायी रूप से एक किया (1134-1155)", "a6602794"], "d": ["राजा स्वेरकर (1134-1155) के शासन में स्वीडनवासी और गोट एक सौ वर्ष तक बारी-बारी से सह-राजा निकालने की व्यवस्था के साथ एकजुट हुए; केंद्रीय राजशाही का संगठन सुदृढ़ हुआ।", "21006781"]},
