"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1138-01-01:0":{"b": ["बोलेस्लाव तृतीय की वसीयत: देश पुत्रों के बीच बँटा, वरिष्ठता प्रणाली आरंभ हुई", "d56e787c"], "d": ["1138 में मरे बोलेस्लाव तृतीय ने राज्य को पुत्रों के बीच बाँटकर 'महा ड्यूक' उपाधि धारण करने वाले सबसे बड़े भाई को केंद्रीय अधिकार देने वाली वरिष्ठता (सेनियोरात) पद्धति लागू की; इस व्यवस्था ने 1138-1320 के बीच के विखंडन (अंतराल) काल को जन्म दिया।", "8a7d818d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1139-07-25:0":{"b": ["मिन्याना में पोप इनोसेंट द्वितीय ने रोजर द्वितीय के राज्य को मान्यता दी", "943c1dad"], "d": ["अनाक्लेतुस की जनवरी 1138 की मृत्यु के बाद रोजर ने इनोसेंट द्वितीय को मान लिया; पोप ने 25 जुलाई 1139 को मिन्याना (मोंतेकासीनो के निकट) में रोजर को सिसिली का राजा, कापुआ का राजकुमार और आपुलिया का ड्यूक निवेशित किया और पुत्रों को दिए उप-सामंतों की पुष्टि की। रोजर ने स्वयं को पोपशाही का सामंत घोषित किया।", "087c0432"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1148-01-01:0":{"b": ["नॉर्मनों ने स्फ़ाक़्स ले लिया (महदिया और क़ाबिस के साथ, 1148)", "e0a296e4"], "d": ["1148 में रोजर द्वितीय के बेड़े ने ज़ीरियों की राजधानी महदिया, साथ ही क़ाबिस (गाबेस) और स्फ़ाक़्स पर अधिकार किया; इन विजयों ने मुवह्हिद ख़लीफ़ा अब्दुलमुमिन को पूर्वी मग़रिब के अभियान पर निकलने को प्रेरित किया।", "a3c4ed88"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1150-01-01:0":{"b": ["एरिक नवम ने चर्च-संगठन व्यवस्थित किया; फ़िनलैंड पर क्रूसेड ने स्वीडन का समुद्र-पार आधिपत्य आरंभ किया", "c67837dc"], "d": ["राजा एरिक नवम (1150-1160) ने स्वीडिश चर्च को पश्चिमी नमूने पर संगठित किया और मूर्तिपूजक फ़िनों के विरुद्ध एक क्रूसेड कर स्वीडन के समुद्र-पार आधिपत्य का आरंभ किया। (अभियान का वर्ष स्रोत में नहीं बताया गया है।)", "be71462d"]},
"OLAYLAR_ORTACAG_ITALYA_DOGU_AVRUPA:1152-01-01:0":{"b": ["निदारोस आर्कबिशप-क्षेत्र स्थापित हुआ; ग्रीनलैंड भी नॉर्वे के चर्च-प्रांत में सम्मिलित हुआ (1152/53)", "07106410"], "d": ["अंग्रेज़ कार्डिनल निकोलस ब्रेकस्पीयर के 1152/53 में त्रॉन्हेम में रहने के दौरान निदारोस आर्कबिशप-क्षेत्र की नींव पड़ी; 1153 में ग्रीनलैंड का बिशप-क्षेत्र भी नॉर्वे के चर्च-प्रांत में सम्मिलित किया गया।", "ed706fc3"]},
